<script setup lang="ts">
import { computed, ref } from 'vue'
import MeshView from './MeshView.vue'
import { createProfile, extrude, revolve, type ProfileName, type SweepAxis } from '../../packages/cg-algorithms/src/sweep'
const mode=ref<'extrude'|'revolve'>('extrude'),profileName=ref<ProfileName>('l-shape'),distance=ref(2),angle=ref(270),segments=ref(16),scale=ref(1),axis=ref<SweepAxis>('y'),wire=ref(true)
const view=ref<InstanceType<typeof MeshView>>()
const profiles:{value:ProfileName;label:string}[]=[{value:'rectangle',label:'Rectangle'},{value:'circle',label:'Circle'},{value:'l-shape',label:'L-shape'},{value:'vase',label:'Vase profile'}]
const state=computed(()=>{try{const profile=createProfile(profileName.value,scale.value);return {profile,mesh:mode.value==='extrude'?extrude(profile,distance.value):revolve(profile,angle.value,segments.value,axis.value),error:''}}catch(error){return {profile:[],mesh:{vertices:[],faces:[]},error:String(error)}}})
const path=computed(()=>state.value.profile.map(([r,h])=>`${30+r*65},${125-h*65}`).join(' '))
function reset(){mode.value='extrude';profileName.value='l-shape';distance.value=2;angle.value=270;segments.value=16;scale.value=1;axis.value='y';wire.value=true;view.value?.resetView()}
</script>
<template>
  <section class="operation-demo" aria-label="Sweep demo">
    <div class="toolbar"><button :aria-pressed="mode==='extrude'" @click="mode='extrude'">Extrude 押し出し</button><button :aria-pressed="mode==='revolve'" @click="mode='revolve'">Revolve 回転</button><label>Profile <select v-model="profileName" aria-label="Profile"><option v-for="p in profiles" :key="p.value" :value="p.value">{{p.label}}</option></select></label><button @click="reset">Reset</button></div>
    <div class="toolbar sliders"><label>Profile scale <input v-model.number="scale" aria-label="Profile scale" type="range" min=".4" max="1.2" step=".1"/>{{scale.toFixed(1)}}</label><label v-if="mode==='extrude'">Distance <input v-model.number="distance" aria-label="Extrude distance" type="range" min="0" max="4" step=".1"/>{{distance.toFixed(1)}}</label><template v-else><label>Angle <input v-model.number="angle" aria-label="Revolve angle" type="range" min="0" max="360" step="15"/>{{angle}}°</label><label>Segments <input v-model.number="segments" aria-label="Revolve segments" type="range" min="3" max="48" step="1"/>{{segments}}</label><label>Axis <select v-model="axis" aria-label="Revolve axis"><option>x</option><option>y</option><option>z</option></select></label></template></div>
    <div class="views"><div class="profile"><strong>① 閉じた2D profile</strong><svg viewBox="0 0 230 250" role="img" aria-label="2D profile。縦破線は回転軸。"><line x1="30" x2="30" y1="15" y2="235" stroke="#64748b" stroke-dasharray="5 4"/><line x1="15" x2="215" y1="125" y2="125" stroke="#cbd5e1"/><polygon :points="path" fill="#bfdbfe" stroke="#1d4ed8" stroke-width="2"/><circle v-for="([r,h],i) in state.profile" :key="i" :cx="30+r*65" :cy="125-h*65" r="2.5" fill="#1e3a8a"/><text x="8" y="15">h</text><text x="210" y="145">r</text></svg></div><div class="process"><strong>② {{mode==='extrude'?'平行移動 →':'軸まわりに回転 →'}}</strong><span>{{mode==='extrude'?`z: −${(distance/2).toFixed(1)} → ${(distance/2).toFixed(1)}`:`${axis}軸 · ${angle}°`}}</span></div><div><strong>③ 3D result · V {{state.mesh.vertices.length}} / F {{state.mesh.faces.length}}</strong><MeshView ref="view" :mesh="state.mesh" :wireframe="wire" :height="245"/></div></div>
    <div class="toolbar"><label><input v-model="wire" type="checkbox"/> Wireframe</label><span v-if="!state.mesh.faces.length">距離・角度0：体積を持つ結果なし</span><span v-else>{{mode==='extrude'?'側面＋三角形のふた（凹L字も保持）':'回転軸上の頂点と360°の継ぎ目を共有'}}</span></div>
    <p v-if="state.error" role="alert">{{state.error}}</p><p v-else>観察：断面の輪郭はどこに現れる？ 回転のsegmentsを増やすと、形の滑らかさと面数はどう変わる？</p>
  </section>
</template>
<style scoped>
.operation-demo{font-size:14px;line-height:1.35;border:1px solid #cbd5e1;border-radius:10px;padding:10px;background:#fff;color:#16324f}.toolbar{display:flex;flex-wrap:wrap;align-items:center;gap:8px}.toolbar label{display:flex;align-items:center;gap:4px}button,select{font:inherit;border:1px solid #94a3b8;border-radius:5px;background:#f8fafc;padding:3px 8px}button[aria-pressed=true]{background:#dbeafe;border-color:#2563eb}.sliders{margin:8px 0}.sliders input{width:95px}.views{display:grid;grid-template-columns:200px 140px minmax(0,1fr);gap:10px}.views strong{font-size:14px}.profile svg{height:245px;width:100%;background:#f8fafc;border-radius:8px}.process{display:flex;flex-direction:column;justify-content:center;gap:12px}.operation-demo p{margin:7px 0 0}@media(max-width:650px){.views{grid-template-columns:1fr}.process{flex-direction:row;justify-content:flex-start;align-items:center;gap:8px}.profile svg{height:180px}.sliders input{width:80px}}
</style>
